export class UserService {
  private db: Database;
  private emailService: EmailService;
  private cache: CacheService;
  private logger: Logger;

  constructor(
    db: Database,
    emailService: EmailService,
    cache: CacheService,
    logger: Logger
  ) {
    this.db = db;
    this.emailService = emailService;
    this.cache = cache;
    this.logger = logger;
  }

  // User CRUD operations
  async createUser(email: string, password: string, name: string): Promise<User> {
    const passwordHash = await hash(password, 12);
    const user = await this.db.users.create({
      email,
      passwordHash,
      name,
      role: 'user',
      preferences: { theme: 'light', notifications: true, language: 'en' }
    });
    await this.emailService.sendWelcomeEmail(user.email, user.name);
    this.logger.info(`User created: ${user.id}`);
    return user;
  }

  async getUserById(id: string): Promise<User | null> {
    const cached = await this.cache.get(`user:${id}`);
    if (cached) return JSON.parse(cached);

    const user = await this.db.users.findById(id);
    if (user) {
      await this.cache.set(`user:${id}`, JSON.stringify(user), 3600);
    }
    return user;
  }

  async updateUser(id: string, updates: Partial<User>): Promise<User> {
    const user = await this.db.users.update(id, updates);
    await this.cache.delete(`user:${id}`);
    this.logger.info(`User updated: ${id}`);
    return user;
  }

  async deleteUser(id: string): Promise<void> {
    await this.db.users.delete(id);
    await this.cache.delete(`user:${id}`);
    this.logger.info(`User deleted: ${id}`);
  }

  // Authentication
  async login(email: string, password: string): Promise<{ user: User; token: string }> {
    const user = await this.db.users.findByEmail(email);
    if (!user) throw new Error('Invalid credentials');

    const valid = await verify(password, user.passwordHash);
    if (!valid) throw new Error('Invalid credentials');

    const token = sign({ userId: user.id, role: user.role }, process.env.JWT_SECRET!, { expiresIn: '24h' });

    await this.db.users.update(user.id, { lastLoginAt: new Date() });
    this.logger.info(`User logged in: ${user.id}`);

    return { user, token };
  }

  async verifyToken(token: string): Promise<{ userId: string; role: string }> {
    return jwtVerify(token, process.env.JWT_SECRET!) as { userId: string; role: string };
  }

  async changePassword(userId: string, oldPassword: string, newPassword: string): Promise<void> {
    const user = await this.getUserById(userId);
    if (!user) throw new Error('User not found');

    const valid = await verify(oldPassword, user.passwordHash);
    if (!valid) throw new Error('Invalid password');

    const passwordHash = await hash(newPassword, 12);
    await this.updateUser(userId, { passwordHash });
    await this.emailService.sendPasswordChangedEmail(user.email);
  }

  async requestPasswordReset(email: string): Promise<void> {
    const user = await this.db.users.findByEmail(email);
    if (!user) return; // Don't reveal if email exists

    const token = sign({ userId: user.id, type: 'reset' }, process.env.JWT_SECRET!, { expiresIn: '1h' });
    await this.emailService.sendPasswordResetEmail(user.email, token);
  }

  // Role management
  async assignRole(userId: string, role: User['role']): Promise<User> {
    return this.updateUser(userId, { role });
  }

  async isAdmin(userId: string): Promise<boolean> {
    const user = await this.getUserById(userId);
    return user?.role === 'admin';
  }

  // Preferences
  async updatePreferences(userId: string, preferences: Partial<UserPreferences>): Promise<User> {
    const user = await this.getUserById(userId);
    if (!user) throw new Error('User not found');

    return this.updateUser(userId, {
      preferences: { ...user.preferences, ...preferences }
    });
  }

  // Analytics
  async getActiveUsers(since: Date): Promise<number> {
    return this.db.users.count({ lastLoginAt: { $gte: since } });
  }

  async getUsersByRole(role: User['role']): Promise<User[]> {
    return this.db.users.findMany({ role });
  }
